      html+='<div style="font-size:12px;color:var(--text-secondary);margin-bottom:6px">DNS-запросы уходят шифрованными к выбранному резолверу</div>';
      html+='<div style="display:flex;gap:6px;background:var(--bg-secondary);padding:4px;border-radius:var(--r-md)"><div class="dohseg seg'+(dON?' on':'')+'" data-v="1" style="cursor:pointer">Вкл</div><div class="dohseg seg'+(!dON?' on':'')+'" data-v="0" style="cursor:pointer">Выкл</div></div>';
      // Бинаря нет — даём поставить ПО ВОЗДУХУ (верб doh_fetch_bin → gh-update fetch-bin сам берёт
