      if(dINST&&!dDOT)
        html+='<div style="font-size:12px;color:var(--text-tertiary);margin-top:7px;line-height:1.45">Бинарь DoT ещё не установлен — переключение заработает после установки. <button id="doh-inst2" style="padding:4px 10px;font-size:11px;margin-left:4px"'+(doh.installing?' disabled':'')+'>'+(doh.installing?'Устанавливаю…':'Установить')+'</button></div>';
      // Пикер резолвера — виден всегда: при выключенном DoH выбор сохранится и применится при включении.
      var dLbl={cloudflare:'Cloudflare (1.1.1.1)',google:'Google (dns.google)',quad9:'Quad9 (9.9.9.9)',adguard:'AdGuard DNS',nextdns:'NextDNS (свой профиль)',custom:'Свой резолвер'};
      var dList=(doh.resolvers&&doh.resolvers.length)?doh.resolvers:['cloudflare','google','quad9','adguard','nextdns','custom'];
